/**
 * One scenario per check of cash-seam-build-standard.
 *
 * Generated by `npx @aipathway/conformance init cash-seam-build-standard`, from
 * https://aipathway.com.au/explore-ai/cash-seam-build-standard, then filled in
 * for the After-Hours Desk node.
 *
 * The runner here delivers named events one at a time, the way a job system's
 * webhooks and a ledger schedule would, and runs the build once per event.
 * Every `holds` reads the world the runner owns: its records and its `calls`.
 *
 * Numbers are from ACMA's fictitious range (0491 570 xxx).
 */

import { CashSeamWorld } from "@aipathway/conformance";

const A = "+61491570156";
const B = "+61491570157";
const DAY = 24 * 60 * 60 * 1000;
const UNATTENDED = new Set(["webhook", "schedule", "poll"]);

/** Deliver one named event and run the build once for it. */
async function deliver(w, build, name, via, payload = {}) {
  const ev = w.makeEvent(name, via, payload);
  w.deliver(ev);
  await build(w.ports());
  w.settle();
  return ev;
}

/** Announce every job the job system has made since the last look, as job_created. */
async function announceJobs(w, build) {
  for (const j of w.unannouncedJobs()) await deliver(w, build, "job_created", "webhook", { jobId: j.id });
}

/**
 * The whole path, for each caller: the call, job created, the customer
 * accepting the sent quote, the job completed, then the ledger schedule after
 * the invoice falls due. `between` runs after the quotes are accepted.
 */
async function fullChain(w, build, callers, { between } = {}) {
  for (const c of callers) await deliver(w, build, "call_received", "webhook", c);
  await announceJobs(w, build);
  for (const s of [...w.sends].filter((x) => x.kind === "quote")) {
    if (w.accept(s.id)) {
      const q = w.quotes.find((x) => x.id === s.id);
      await deliver(w, build, "quote_accepted", "webhook", { quoteId: q.id, jobId: q.jobId });
    }
  }
  if (between) await between();
  for (const j of [...w.jobs]) {
    if (w.complete(j.id)) await deliver(w, build, "job_completed", "webhook", { jobId: j.id });
  }
  w.advance(15 * DAY);
  await deliver(w, build, "invoice_overdue", "schedule");
}

const sendCalls = (w) => w.calls.filter((c) => c.port === "issue_notice" || c.port === "send_sms");
const searches = (w) => w.calls.filter((c) => c.port === "read_job" && c.request?.search);
const eventName = (w, id) => w.eventById(id)?.name;

export const scenarios = [
  {
    checkId: "identity-from-the-system-of-record",
    // 1. Ids from the system of record, never a name or a phone.
    // Inject: two open jobs for two customers who share a name; one gets a quote
    // accepted and is completed.
    // Assert: the quote carries its job's id, the invoice that quote's id and that
    // job's id, and no name or phone search runs on a downstream event.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-1", customerName: "Mrs Lee", phone: A, status: "open" },
          { id: "JS-2", customerName: "Mrs Lee", phone: B, status: "open" },
        ],
      }),
    drive: async (build, w) => {
      await deliver(w, build, "job_created", "webhook", { jobId: "JS-2" });
      const q = w.quotesFor("JS-2")[0];
      if (q && w.accept(q.id)) await deliver(w, build, "quote_accepted", "webhook", { quoteId: q.id, jobId: "JS-2" });
      w.complete("JS-2");
      await deliver(w, build, "job_completed", "webhook", { jobId: "JS-2" });
    },
    holds: (w) => {
      const issued = w.issuedIds();
      const q = w.quotes;
      const inv = w.invoices;
      const downstreamSearch = searches(w).some((c) => eventName(w, c.request.event) !== "call_received");
      return (
        q.length === 1 && q[0].jobId === "JS-2" &&
        inv.length === 1 && inv[0].jobId === "JS-2" && inv[0].quoteId === q[0].id &&
        w.invoicesFor("JS-1").length === 0 &&
        issued.has(inv[0].quoteId) && issued.has(inv[0].jobId) &&
        !downstreamSearch
      );
    },
    describe: (w) => `quotes ${JSON.stringify(w.quotes.map((q) => [q.id, q.jobId]))}; invoices ${JSON.stringify(w.invoices.map((i) => [i.id, i.quoteId, i.jobId]))}; downstream searches ${searches(w).filter((c) => eventName(w, c.request.event) !== "call_received").length}`,
  },
  {
    checkId: "one-job-per-enquiry",
    // 2. One job per enquiry. Inject: the same number rings, then uses the web form.
    // Assert: one job; the second enquiry has duplicate_of; a read for open jobs on
    // that number preceded every job write.
    world: () => new CashSeamWorld(),
    drive: async (build, w) => {
      await deliver(w, build, "call_received", "webhook", { phone: A, customerName: "Mrs Lee", door: "phone" });
      w.advance(10 * 60 * 1000);
      await deliver(w, build, "call_received", "webhook", { phone: A, customerName: "Mrs Lee", door: "web" });
    },
    holds: (w) => {
      const jobs = w.jobsFor(A);
      if (jobs.length !== 1 || w.enquiries.length !== 2) return false;
      const dup = w.enquiries[1].duplicateOf === jobs[0].id && !w.enquiries[0].duplicateOf;
      const writes = w.calls.map((c, i) => [c, i]).filter(([c]) => c.port === "write_job");
      const readFirst = writes.every(([, i]) => w.calls.slice(0, i).some((c) => c.port === "read_job" && c.request?.search?.phone === A));
      return dup && readFirst && writes.length === 2;
    },
    describe: (w) => `${w.jobsFor(A).length} job(s); enquiries ${JSON.stringify(w.enquiries)}`,
  },
  {
    checkId: "no-external-id-no-write",
    // 3. A write without an external id is not written. Inject: the full chain, a
    // null id on the quote write for one job and on the invoice write for another.
    // Assert: each is escalated write_failed; nothing released, sent or chased for
    // either; no later record carries a null or invented reference.
    world: () => new CashSeamWorld({ nullQuoteFor: ["JS-1001"], nullInvoiceFor: ["JS-1002"] }),
    drive: (build, w) =>
      fullChain(w, build, [
        { phone: A, customerName: "Mrs Lee" },
        { phone: B, customerName: "Mr Okoro" },
      ]),
    holds: (w) => {
      const esc = (ref, stage) => w.escalations.some((e) => e.ref === ref && e.stage === stage && e.reason === "write_failed" && e.owner);
      const issued = w.issuedIds();
      const q2 = w.quotesFor("JS-1002");
      const touchedA = [...w.releases, ...w.sends].some((x) => w.quotesFor("JS-1001").some((q) => q.id === x.id)) || w.invoicesFor("JS-1001").length > 0;
      const invoiceForB = w.invoicesFor("JS-1002").length > 0 || w.releases.some((r) => r.kind === "invoice") || w.sends.some((s) => s.kind === "invoice");
      const noNullRefs = w.quotes.every((q) => q.jobId && issued.has(q.jobId)) && w.invoices.every((i) => i.jobId && issued.has(i.jobId));
      const sendsReal = w.sends.every((s) => issued.has(s.id));
      return w.jobs.length === 2 && esc("JS-1001", "quote") && esc("JS-1002", "invoice") && q2.length === 1 && !touchedA && !invoiceForB && w.chases.length === 0 && noNullRefs && sendsReal;
    },
    describe: (w) => `escalations ${JSON.stringify(w.escalations.map((e) => [e.stage, e.ref, e.reason, e.owner]))}; invoices ${w.invoices.length}; chases ${w.chases.length}`,
  },
  {
    checkId: "the-chain-carries-the-id",
    // 4. The chain carries the id. Inject: one enquiry through the whole path.
    // Assert: one job, quote, invoice and chase, each naming the one before, and the
    // chase's invoice id seen in a ledger read before the chase.
    world: () => new CashSeamWorld(),
    drive: (build, w) => fullChain(w, build, [{ phone: A, customerName: "Mrs Lee" }]),
    holds: (w) => {
      if (w.jobs.length !== 1 || w.quotes.length !== 1 || w.invoices.length !== 1 || w.chases.length !== 1) return false;
      const [j] = w.jobs;
      const [q] = w.quotes;
      const [i] = w.invoices;
      const [ch] = w.chases;
      const chaseAt = w.calls.findIndex((c) => c.port === "send_sms" && c.request.send === "chase");
      const seenInLedger = w.calls.slice(0, chaseAt).some((c) => c.port === "read_ledger" && c.request?.ledger && c.response?.ids?.includes(ch.invoiceId));
      return q.jobId === j.id && i.quoteId === q.id && i.jobId === j.id && ch.invoiceId === i.id && seenInLedger;
    },
    describe: (w) => `job ${w.jobs.map((j) => j.id)}; quote ${JSON.stringify(w.quotes.map((q) => [q.id, q.jobId]))}; invoice ${JSON.stringify(w.invoices.map((i) => [i.id, i.quoteId, i.jobId]))}; chase ${JSON.stringify(w.chases.map((c) => c.invoiceId))}`,
  },
  {
    checkId: "confirmation-is-not-a-write",
    // 5. A confirmation is not a write and not a release. Inject: the full chain,
    // one quote write that returns an id and a success message and stores nothing.
    // Assert: that quote is escalated and never released or sent; every send is
    // preceded by a read-back that returned the record and a named release.
    world: () => new CashSeamWorld({ phantomQuoteFor: ["JS-1001"] }),
    drive: (build, w) =>
      fullChain(w, build, [
        { phone: A, customerName: "Mrs Lee" },
        { phone: B, customerName: "Mr Okoro" },
      ]),
    holds: (w) => {
      const ghost = w.phantomIds[0];
      if (!ghost) return false;
      const ghostTouched = w.releases.some((r) => r.id === ghost) || w.sends.some((s) => s.id === ghost);
      const escalated = w.escalations.some((e) => e.ref === "JS-1001" && e.stage === "quote" && e.owner);
      const sends = sendCalls(w);
      const everySendBacked = sends.every((s) => {
        const i = w.calls.indexOf(s);
        const before = w.calls.slice(0, i);
        const id = s.request.id;
        const readBack = before.some((c) => (c.port === "read_job" && c.request?.quote === id && c.response?.id === id) || (c.port === "read_ledger" && c.request?.invoice === id && c.response?.id === id));
        const released = before.some((c) => c.port === "gate" && c.request?.id === id && (c.request.person || c.request.rule));
        return readBack && released;
      });
      return !ghostTouched && escalated && sends.length >= 3 && everySendBacked;
    },
    describe: (w) => `phantom ${JSON.stringify(w.phantomIds)}; sends ${JSON.stringify(w.sends.map((s) => [s.kind, s.id]))}; escalations ${JSON.stringify(w.escalations.map((e) => [e.stage, e.ref, e.reason]))}`,
  },
  {
    checkId: "named-unattended-trigger",
    // 6. Every hop from a named event. Inject: the full chain as events with nobody
    // in a session, plus a chat message asking for an invoice.
    // Assert: every write and send names the event that woke it, delivered by
    // webhook, schedule or poll, of the right kind for its hop; all four hops ran.
    world: () => new CashSeamWorld(),
    drive: (build, w) =>
      fullChain(w, build, [{ phone: A, customerName: "Mrs Lee" }], {
        between: () => deliver(w, build, "chat_message", "chat", { text: "can you raise the invoice for Mrs Lee now please", jobId: "JS-1001" }),
      }),
    holds: (w) => {
      const expect = { write_job: "call_received", draft_quote: "job_created", write_invoice: "job_completed" };
      const writes = w.calls.filter((c) => c.port in expect);
      const writesOk = writes.every((c) => {
        const ev = w.eventById(c.request.trigger);
        return ev && UNATTENDED.has(ev.via) && ev.name === expect[c.port];
      });
      const sendExpect = { quote: "job_created", invoice: "job_completed", chase: "invoice_overdue" };
      const sendsOk = w.sends.every((s) => {
        const ev = w.eventById(s.trigger);
        return ev && UNATTENDED.has(ev.via) && ev.name === sendExpect[s.kind];
      });
      const chat = w.delivered.find((e) => e.via === "chat");
      const nothingFromChat = Boolean(chat) && !w.calls.some((c) => c.request?.trigger === chat.id || c.request?.event === chat.id && c.verb === "write");
      const allHops = w.jobs.length === 1 && w.quotes.length === 1 && w.invoices.length === 1 && w.chases.length === 1;
      return writes.length === 3 && writesOk && sendsOk && nothingFromChat && allHops;
    },
    describe: (w) => `writes ${JSON.stringify(w.calls.filter((c) => ["write_job", "draft_quote", "write_invoice"].includes(c.port)).map((c) => [c.port, eventName(w, c.request.trigger)]))}; sends ${JSON.stringify(w.sends.map((s) => [s.kind, eventName(w, s.trigger)]))}`,
  },
  {
    checkId: "exception-owner-travels",
    // 7. The exception names its owner and the next step does not pass it.
    // Inject: two jobs complete; one already carries an open exception; the invoice
    // write for the other returns no id.
    // Assert: no invoice past the exception, a hold naming its owner; the failed
    // write escalated to the owner the business set for invoices.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-1", customerName: "Mrs Lee", phone: A, status: "open", exception: { reason: "scope disputed", owner: "Sam Okafor" } },
          { id: "JS-2", customerName: "Mr Okoro", phone: B, status: "open" },
        ],
        nullInvoiceFor: ["JS-2"],
      }),
    drive: async (build, w) => {
      for (const id of ["JS-1", "JS-2"]) {
        w.complete(id);
        await deliver(w, build, "job_completed", "webhook", { jobId: id });
      }
    },
    holds: (w) => {
      const named = new Set([...Object.values(w.owners), "Sam Okafor"]);
      const hold = w.escalations.some((e) => e.ref === "JS-1" && e.owner === "Sam Okafor");
      const failed = w.escalations.some((e) => e.ref === "JS-2" && e.reason === "write_failed" && e.owner === w.owners.invoice);
      const owned = w.escalations.length > 0 && w.escalations.every((e) => e.owner && named.has(e.owner));
      const noInvoicePast = w.invoicesFor("JS-1").length === 0 && !w.calls.some((c) => c.port === "write_invoice" && c.request.jobId === "JS-1");
      const travels = w.job("JS-2")?.exception?.owner === w.owners.invoice;
      return hold && failed && owned && noInvoicePast && travels;
    },
    describe: (w) => `escalations ${JSON.stringify(w.escalations.map((e) => [e.ref, e.reason, e.owner]))}; invoice writes ${w.calls.filter((c) => c.port === "write_invoice").map((c) => c.request.jobId)}`,
  },
  {
    checkId: "survives-the-builder",
    // 8. It survives the builder. A precondition: closed by evidence, never by a
    // run. The runner reports it as evidence_required whatever this returns.
    world: () => new CashSeamWorld(),
    drive: () => {},
    holds: () => false,
    describe: () => "declared, not run",
  },
];

// The checks a stub cannot pass, and is not asked to.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 9. The pass test passes, on the business's own job system and ledger.
    // Deliberately unpassable on a stub.
    world: () => new CashSeamWorld(),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
